import api from './api';

export const vendorService = {
  // Create or update vendor profile
  createOrUpdateProfile: async (profileData) => {
    try {
      const response = await api.post('/api/vendor/profile', profileData);
      return response;
    } catch (error) {
      throw error;
    }
  },

  // Get vendor profile
  getProfile: async () => {
    try {
      const response = await api.get('/api/vendor/profile');
      return response;
    } catch (error) {
      throw error;
    }
  },

  // Create application
  createApplication: async () => {
    try {
      const response = await api.post('/api/vendor/application');
      return response;
    } catch (error) {
      throw error;
    }
  },

  // Submit application
  submitApplication: async (applicationId) => {
    try {
      const response = await api.put(`/api/vendor/application/${applicationId}/submit`);
      return response;
    } catch (error) {
      throw error;
    }
  },

  // Get vendor applications
  getApplications: async () => {
    try {
      const response = await api.get('/api/vendor/applications');
      return response;
    } catch (error) {
      throw error;
    }
  },

  // Get vendor dashboard data
  getDashboardData: async () => {
    try {
      const response = await api.get('/api/vendor/dashboard');
      return response;
    } catch (error) {
      throw error;
    }
  },

  // Public vendor endpoints (no auth required)
  addPublicVendor: async (vendorData) => {
    try {
      const response = await api.post('/addVendor', vendorData);
      return response;
    } catch (error) {
      throw error;
    }
  },

  getAllPublicVendors: async () => {
    try {
      const response = await api.get('/getAllVendors');
      return response;
    } catch (error) {
      throw error;
    }
  }
};
